function CountOpenBrackets(brackets: string): int
    reads brackets
{
    var count := 0;
    var i := 0;
    while i < brackets.Length
        invariant 0 <= count <= i
        invariant i <= brackets.Length
    {
        if brackets[i] == '(' then
            count := count + 1;
        i := i + 1;
    }
    return count;
}

function CountCloseBrackets(brackets: string): int
    reads brackets
{
    var count := 0;
    var i := 0;
    while i < brackets.Length
        invariant 0 <= count <= i
        invariant i <= brackets.Length
    {
        if brackets[i] == ')' then
            count := count + 1;
        i := i + 1;
    }
    return count;
}

function IsValidOrder(brackets: string): bool
    reads brackets
{
    var balance := 0;
    var i := 0;
    while i < brackets.Length
        invariant 0 <= balance <= i
        invariant i <= brackets.Length
    {
        if brackets[i] == '(' then
            balance := balance + 1;
        else if brackets[i] == ')' then
            balance := balance - 1;
        if balance < 0 then
            return false;
        i := i + 1;
    }
    return balance == 0;
}
